mapper.delete:
DELETE FROM vm_emergency_warning_event_rel WHERE 1 = 1
AND event_code IN
#{item}
AND event_code = #{eventCode}

mapper.select:
SELECT id, warning_order_id, event_code, tenant_id, industry_code, app_ver_code, create_time, creator, update_time, modifier, delete_flag FROM vm_emergency_warning_event_rel WHERE delete_flag = 0
AND warning_order_id = #{warningOrderId}
AND event_code = #{eventCode}
ORDER BY warning_order_id ASC
